    assert_eq!(pair_link_macro.matches("paid!(").count(), 15);
    let tail_owner = include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/src/cleanup_plan/replay/ordinary_plan_history/comparison_owner/before_main_b692.rs"
