                    budget.reserve_bytes(
                        function,
                        physical_clone::conversion_bytes::<std::rc::Rc<SkeletonObservation>, _>(
                            &observation,
                        ),
                        "plan branch observation push",
                    )?;
                    branch.push(observation.into());
                    skeleton_queue_push(
                        budget,
                        function,
                        &mut queue,
                        (edge.to, branch),
                        "plan branch state push",
