                        }
                    };
                    if let ReplayBudget {
                        payer: AllocationPayer::ActiveBuilder,
                        ..
                    } = budget
                    {
                        budget.reserve_bytes(
                            function,
                            branch_clone::production_capacity::production_inline_controls::<
                                std::rc::Rc<SkeletonObservation>,
                            >(),
                            "branch clone receiving controls",
                        )?;
                    } else {
